+		_ = tmp.Close()
+		return ex.Wrapf(writeErr, "failed to write temporary file %s", tmpPath)
+	}
+
+	if closeErr := tmp.Close(); closeErr != nil {
+		return ex.Wrapf(closeErr, "failed to close temporary file %s", tmpPath)
+	}
+
